@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{--ink:#e7e5d7;--muted:#9c9e8f;--lime:#c0cf82;--rust:#cc7959;--panel:rgba(16,21,17,.82);--line:rgba(227,230,204,.16)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101611;color:var(--ink);font-family:'DM Sans',sans-serif;user-select:none;-webkit-user-select:none;touch-action:none}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#18231d}#game{display:block;width:100%;height:100%;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 45%,transparent 42%,rgba(5,9,7,.21) 100%),linear-gradient(180deg,rgba(5,9,7,.43),transparent 21%,transparent 70%,rgba(5,9,7,.63)}.topbar{position:absolute;top:0;left:0;right:0;height:90px;padding:20px 34px;display:flex;align-items:flex-start;gap:44px;background:linear-gradient(180deg,rgba(8,13,11,.8),transparent);pointer-events:none}.brand{display:flex;gap:10px;align-items:center;font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:17px;letter-spacing:2px;line-height:1}.brand small{display:block;color:var(--lime);font-size:10px;letter-spacing:3.3px;margin-top:5px}.brand-mark{width:34px;height:34px;display:grid;place-items:center;border:1px solid rgba(192,207,130,.65);color:var(--lime);font-size:24px;transform:rotate(45deg);font-family:serif}.brand-mark::first-letter{transform:rotate(-45deg)}.mission-card{padding-left:17px;border-left:1px solid rgba(192,207,130,.55);display:flex;flex-direction:column;gap:3px;max-width:320px}.eyebrow,.mission-card .eyebrow{font-size:9px;letter-spacing:1.9px;color:var(--lime);font-weight:700}.mission-card strong{font-family:'Barlow Condensed',sans-serif;font-size:21px;letter-spacing:.8px;font-weight:600}.mission-sub{font-size:11px;color:#b1b2a5}.top-right{margin-left:auto;display:flex;align-items:center;gap:17px;pointer-events:auto}.day-tag{font-size:10px;letter-spacing:1.4px;color:#d0d0c4;padding:8px 11px;background:rgba(15,21,17,.53);border:1px solid var(--line)}.day-tag i{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--rust);margin-right:7px;box-shadow:0 0 9px var(--rust)}.day-tag span{color:#777d70;margin:0 5px}.icon-btn{width:34px;height:34px;background:rgba(17,24,19,.65);border:1px solid var(--line);font-size:15px;cursor:pointer}.left-hud{position:absolute;left:34px;top:108px;display:flex;flex-direction:column;gap:9px;width:210px}.status-card,.radio-card{background:var(--panel);border:1px solid var(--line);backdrop-filter:blur(8px);padding:11px 13px}.status-head,.status-bottom{display:flex;align-items:center;justify-content:space-between;font-size:9px;letter-spacing:1.4px;color:#bfc2b2}.status-head span:last-child{font-family:'Barlow Condensed';font-size:15px;color:var(--ink);letter-spacing:1px}.meter{height:4px;background:rgba(255,255,255,.13);margin-top:7px}.meter i{height:100%;width:100%;display:block;background:var(--lime);transition:width .2s}.status-bottom{margin-top:10px;color:#8f9685}.meter.stamina{height:3px;width:105px;margin:0}.meter.stamina i{background:#a9b5a0}.radio-card{display:flex;align-items:center;gap:9px;padding:9px 11px}.radio-icon{font-size:22px;color:var(--lime)}.radio-card small{display:block;color:#9a9d8e;font-size:8px;letter-spacing:1.5px}.radio-card strong{font-family:'Barlow Condensed';font-size:13px;font-weight:600;letter-spacing:.9px}.signal-bars{margin-left:auto;display:flex;align-items:flex-end;gap:2px;height:15px}.signal-bars i{width:3px;background:var(--lime);height:5px;opacity:.8}.signal-bars i:nth-child(2){height:8px}.signal-bars i:nth-child(3){height:11px}.signal-bars i:nth-child(4){height:15px;opacity:.2}.right-hud{position:absolute;right:34px;top:106px;display:flex;align-items:flex-end;flex-direction:column;gap:9px}.mini-map{position:relative;width:148px;height:148px;border:1px solid rgba(216,220,192,.35);background:rgba(15,21,17,.73);padding:4px;box-shadow:0 8px 30px #080d0a55}.mini-map canvas{width:100%;height:100%;opacity:.9}.map-label{position:absolute;bottom:7px;left:9px;padding:3px 5px;background:#111a14d9;font-size:8px;letter-spacing:1.5px;color:#c5c6b5}.map-dot{position:absolute;left:50%;top:50%;width:6px;height:6px;background:#d9e89b;border:1px solid #fff;border-radius:50%;box-shadow:0 0 9px #dcf4a0}.threat-pill{display:flex;align-items:center;gap:7px;padding:6px 9px;background:rgba(15,21,17,.67);border:1px solid rgba(204,121,89,.3);font-size:8px;letter-spacing:1.4px;color:#d6a18b}.pulse{width:6px;height:6px;background:#ce7457;border-radius:50%;box-shadow:0 0 8px #d66e4b;animation:pulse 1.8s infinite}@keyframes pulse{50%{opacity:.35}}.bottom-hud{position:absolute;bottom:0;left:0;right:0;min-height:91px;padding:15px 34px 18px;display:flex;align-items:center;background:linear-gradient(0deg,rgba(8,13,11,.9),rgba(8,13,11,.58) 70%,transparent);gap:22px}.weapon-block{display:flex;align-items:center;gap:12px;min-width:245px}.weapon-glyph{font-size:30px;color:var(--lime);width:38px;text-align:center;transform:rotate(-35deg)}.weapon-block .eyebrow{display:block;color:#9ea28e;font-size:8px;letter-spacing:1.5px}.weapon-block strong{font-family:'Barlow Condensed';font-size:17px;letter-spacing:1px}.weapon-key{border:1px solid var(--line);padding:4px 6px;font-size:10px;color:var(--lime);margin-left:5px}.weapon-key small{display:block;color:#8b9082;font-size:7px;letter-spacing:1px}.ammo-block{min-width:105px;font-family:'Barlow Condensed';display:grid;grid-template-columns:auto auto auto;align-items:center;gap:5px}.ammo-block>span:first-child{font-size:29px;font-weight:700}.ammo-block>span:nth-child(3){font-size:17px;color:#a6a99b}.ammo-block i{font-style:normal;color:#6f766b}.ammo-caption{grid-column:1/4;font:8px 'DM Sans';letter-spacing:1.5px;color:#a2a596}.ammo-caption span{color:#737b6d;margin-left:9px}.hint-block{margin-left:auto;color:#b4b6a8;font-size:9px;letter-spacing:1.1px}.keycap{font-family:'Barlow Condensed';font-size:10px;color:#e1e2d4;border:1px solid #aeb39c55;padding:3px 5px;background:#d1d6b40b}.hint-sep{color:#6e7769;margin:0 8px}.overlay{position:absolute;inset:0;display:grid;place-items:center;background:rgba(8,13,11,.4);backdrop-filter:blur(2px);transition:opacity .3s}.overlay.hidden,.journal.hidden{display:none}.intro-card{width:min(440px,calc(100vw - 42px));padding:33px 42px 28px;background:linear-gradient(145deg,rgba(24,32,25,.96),rgba(14,20,17,.98));border:1px solid rgba(201,211,164,.31);box-shadow:0 25px 100px #0009;position:relative;text-align:center}.intro-card::before,.intro-card::after{content:'';position:absolute;width:18px;height:18px;border-color:var(--lime);opacity:.7}.intro-card::before{left:-1px;top:-1px;border-left:1px solid;border-top:1px solid}.intro-card::after{right:-1px;bottom:-1px;border-right:1px solid;border-bottom:1px solid}.intro-kicker{display:flex;align-items:center;gap:10px;justify-content:center;color:#c1ca9f;font-size:9px;letter-spacing:2.5px}.kicker-line{width:24px;height:1px;background:#a7b27c}.intro-title{font-family:'Barlow Condensed';font-weight:900;font-size:78px;line-height:.95;letter-spacing:3px;margin:13px 0 3px;color:#e8e4d3;text-shadow:0 3px 30px #d5cc9a33}.intro-title span{color:var(--lime)}.intro-subtitle{font-family:'Barlow Condensed';font-size:17px;line-height:1.2;letter-spacing:3px}.intro-subtitle em{font-style:normal;color:#c0cf82}.story-rule{height:1px;background:linear-gradient(90deg,transparent,#a8b28277,transparent);margin:22px 0 15px}.intro-card p,.small-dialog p{color:#adb1a2;font-size:12px;line-height:1.8;margin:0 auto 21px;max-width:330px}.primary-btn{width:100%;height:48px;background:var(--lime);border:0;color:#182019;font-family:'Barlow Condensed';font-weight:700;font-size:15px;letter-spacing:1.7px;cursor:pointer;transition:background .2s,transform .2s}.primary-btn span{font-size:19px;margin-left:8px}.primary-btn:hover{background:#d6e5a0;transform:translateY(-1px)}.start-note{font-size:8px;color:#828a7d;letter-spacing:1.3px;margin-top:15px}.small-dialog{width:min(370px,calc(100vw - 40px));padding:30px;background:rgba(17,24,19,.97);border:1px solid #c1cc8b77;text-align:center;box-shadow:0 20px 100px #000a}.small-dialog h2{font-family:'Barlow Condensed';font-size:48px;letter-spacing:2px;margin:9px 0}.journal{position:absolute;left:50%;bottom:115px;transform:translateX(-50%);width:min(520px,calc(100vw - 30px));padding:16px 20px;background:rgba(14,20,16,.94);border-left:2px solid var(--lime);box-shadow:0 10px 40px #0008;z-index:5}.journal span{display:block;color:var(--lime);font-size:8px;letter-spacing:1.7px;margin-bottom:7px}.journal strong{display:block;font:500 15px 'Barlow Condensed';letter-spacing:.3px}.journal button{background:none;border:0;color:#c7d28f;font-size:9px;letter-spacing:1.5px;margin-top:11px;cursor:pointer}.toast{position:absolute;left:50%;top:24%;transform:translate(-50%,-10px);opacity:0;background:#111a14e8;border:1px solid #c1cc8b55;padding:10px 18px;color:#e5e5d7;font:600 11px 'Barlow Condensed';letter-spacing:1.5px;transition:all .25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.mobile-controls{display:none}
@media(max-width:760px){.topbar{height:68px;padding:13px 15px;gap:13px}.brand{font-size:13px;gap:7px;letter-spacing:1.4px}.brand-mark{width:28px;height:28px;font-size:19px}.brand small{font-size:8px;letter-spacing:2px;margin-top:3px}.mission-card{padding-left:10px;max-width:205px}.mission-card strong{font-size:16px}.mission-card .eyebrow{font-size:7px}.mission-sub{font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:190px}.top-right{gap:7px}.day-tag{font-size:8px;padding:7px}.icon-btn{width:30px;height:30px}.left-hud{left:12px;top:78px;width:155px;gap:5px}.status-card{padding:8px 9px}.status-head{font-size:8px}.radio-card{padding:7px 8px;gap:6px}.radio-card strong{font-size:11px}.radio-card small{font-size:7px}.radio-icon{font-size:18px}.right-hud{right:12px;top:77px;gap:5px}.mini-map{width:108px;height:108px;padding:3px}.threat-pill{font-size:7px;padding:5px 7px}.bottom-hud{padding:9px 13px calc(13px + env(safe-area-inset-bottom));min-height:68px;gap:10px}.weapon-block{min-width:0;gap:7px}.weapon-glyph{font-size:23px;width:27px}.weapon-block strong{font-size:13px}.weapon-block .eyebrow{font-size:7px}.weapon-key,.hint-block{display:none}.ammo-block{margin-left:auto;min-width:72px;gap:3px}.ammo-block>span:first-child{font-size:24px}.ammo-block>span:nth-child(3){font-size:14px}.ammo-caption{font-size:7px}.ammo-caption span{margin-left:5px}.mobile-controls{display:block;position:absolute;inset:0;pointer-events:none}.stick-zone{position:absolute;left:15px;bottom:calc(86px + env(safe-area-inset-bottom));width:120px;height:120px;pointer-events:auto;display:flex;align-items:center;justify-content:center}.stick-base{width:94px;height:94px;border:1px solid #e4e6d542;border-radius:50%;background:#1720197a;box-shadow:inset 0 0 20px #0005;display:grid;place-items:center}.stick-knob{width:42px;height:42px;border-radius:50%;background:#c1ce8a9c;border:1px solid #e6eac17a;box-shadow:0 3px 12px #0008;transform:translate(0,0)}.stick-zone>span{position:absolute;bottom:-3px;font-size:7px;letter-spacing:1.5px;color:#d5d9c4aa}.touch-actions{position:absolute;right:12px;bottom:calc(83px + env(safe-area-inset-bottom));width:154px;height:151px;pointer-events:none}.touch-actions button{pointer-events:auto;position:absolute;border-radius:50%;cursor:pointer;touch-action:none;display:flex;flex-direction:column;align-items:center;justify-content:center}.fire-touch{right:0;top:17px;width:67px;height:67px;background:#b8c982d9;border:1px solid #eef2c7;color:#152019;box-shadow:0 3px 18px #0008}.fire-touch span{font-size:24px}.fire-touch small,.action-touch small{font-size:7px;letter-spacing:1px}.action-touch{width:43px;height:43px;background:#18231bd9;border:1px solid #cdd4ad88;color:#d8dfb0;font-size:18px}.action-touch small{font-size:6px}.action-touch#reload-touch{right:72px;top:6px}.action-touch#swap-touch{right:78px;top:61px}.action-touch#sprint-touch{right:24px;top:94px}.overlay{padding:12px}.intro-card{padding:25px 25px 20px;width:min(380px,calc(100vw - 35px))}.intro-title{font-size:64px}.intro-card p{font-size:11px;margin-bottom:15px}.story-rule{margin:16px 0 12px}.primary-btn{height:44px}.start-note{font-size:7px}.journal{bottom:calc(220px + env(safe-area-inset-bottom));padding:12px 14px}.journal strong{font-size:13px}}
@media(max-height:520px) and (orientation:landscape){.topbar{padding-top:8px;height:56px}.left-hud{top:60px}.right-hud{top:59px}.mini-map{width:86px;height:86px}.bottom-hud{min-height:56px;padding-top:5px;padding-bottom:5px}.mobile-controls .stick-zone{width:90px;height:90px;bottom:62px}.stick-base{width:70px;height:70px}.stick-knob{width:34px;height:34px}.touch-actions{transform:scale(.78);transform-origin:bottom right;bottom:59px}.journal{bottom:70px}.intro-card{padding:15px 24px}.intro-title{font-size:52px;margin:7px}.intro-card p{margin-bottom:10px}.story-rule{margin:10px 0}.start-note{margin-top:8px}}

(()=>{'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),mapCanvas=document.getElementById('map'),mctx=mapCanvas.getContext('2d');
const ui={objective:document.getElementById('objective'),sub:document.getElementById('mission-sub'),health:document.getElementById('health-value'),healthBar:document.getElementById('health-bar'),stamina:document.getElementById('stamina-bar'),ammo:document.getElementById('ammo-current'),reserve:document.getElementById('ammo-reserve'),weapon:document.getElementById('weapon-name'),type:document.getElementById('weapon-type'),glyph:document.getElementById('weapon-glyph'),threat:document.getElementById('threat-text'),toast:document.getElementById('toast'),start:document.getElementById('start-screen'),pause:document.getElementById('pause-screen'),end:document.getElementById('end-screen'),journal:document.getElementById('journal')};
const W=1900,H=1300,keys={},rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
let vw=innerWidth,vh=innerHeight,dpr=1,camera={x:0,y:0},running=false,started=false,paused=false,gameOver=false,last=0,toastTimer=0,shake=0;
const player={x:260,y:650,r:15,angle:0,hp:100,stamina:100,speed:178,invuln:0};
const weapons=[{name:'M9 FIELD PISTOL',type:'SIDEARM · 9MM',mag:12,reserve:48,capacity:12,damage:48,rate:.29,range:470,reload:0,spread:.055,glyph:'⌁'},{name:'AK-74 CARBINE',type:'RIFLE · 5.45MM',mag:30,reserve:90,capacity:30,damage:34,rate:.12,range:610,reload:0,spread:.035,glyph:'╱'}];let wi=0,kills=0,objectiveStage=0,fireClock=0,hitFlash=0,recorded=false;
const zeds=[],bullets=[],particles=[],trees=[],rocks=[],cars=[],loot=[];
function makeWorld(){let seed=98423;const sr=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
 for(let i=0;i<330;i++){let x=sr()*W,y=sr()*H;if(Math.abs(y-650)<105)continue;trees.push({x,y,r:10+sr()*19,t:sr()})}
 for(let i=0;i<80;i++){let x=sr()*W,y=sr()*H;if(Math.abs(y-650)<80)continue;rocks.push({x,y,r:3+sr()*8})}
 cars.push({x:580,y:575,a:.10,c:'#5e6558',type:0},{x:860,y:714,a:-.14,c:'#784b3d',type:1},{x:1170,y:579,a:.04,c:'#55574e',type:0},{x:1460,y:724,a:.08,c:'#7b715a',type:1});
 for(let i=0;i<10;i++){let x=rand(380,1330),y=rand(480,815);if(Math.abs(y-650)<80)y+=Math.sign(y-650||1)*90;spawnZed(x,y)}
 loot.push({x:700,y:830,type:'ammo',used:false},{x:1080,y:460,type:'med',used:false},{x:1330,y:810,type:'ammo',used:false});}
function spawnZed(x,y){zeds.push({x,y,r:13,hp:70,speed:rand(34,53),attack:0,stun:0,dead:false,phase:rand(0,6),type:Math.random()});}
makeWorld();
function resize(){dpr=Math.min(devicePixelRatio||1,2);vw=innerWidth;vh=innerHeight;canvas.width=Math.floor(vw*dpr);canvas.height=Math.floor(vh*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastTimer=2.2}
function setWeapon(){let w=weapons[wi];ui.weapon.textContent=w.name;ui.type.textContent=w.type;ui.glyph.textContent=w.glyph;ui.ammo.textContent=w.mag;ui.reserve.textContent=w.reserve}
function updateHUD(){ui.health.textContent=Math.ceil(player.hp)+'%';ui.healthBar.style.width=player.hp+'%';ui.healthBar.style.background=player.hp<30?'#cf7259':'#c0cf82';ui.stamina.style.width=player.stamina+'%';setWeapon();
 if(objectiveStage===0){ui.objective.textContent=`Reach the Pine Ridge relay (${Math.max(0,Math.round((1580-player.x)/10))} m)`;ui.sub.textContent='Follow the signal. Avoid drawing a crowd.'}
 else if(objectiveStage===1){ui.objective.textContent=`Clear the relay approach · ${zeds.filter(z=>!z.dead).length} walkers`;ui.sub.textContent='The gate is blocked. Make the road safe.'}
 else if(objectiveStage===2){ui.objective.textContent='Reach the relay station';ui.sub.textContent='The gate is open. Get inside.'}
 ui.threat.textContent=zeds.filter(z=>!z.dead).length>5?'THE DEAD ARE LISTENING':'MOVEMENT NEARBY';document.querySelector('.signal-bars i:last-child').style.opacity=player.x>1100?'.9':'.2';}
function startGame(){started=true;running=true;paused=false;ui.start.classList.add('hidden');last=performance.now();requestAnimationFrame(loop);toast('KEEP MOVING. THE SIGNAL IS AHEAD.')}
function restart(){player.x=260;player.y=650;player.hp=100;player.stamina=100;kills=0;objectiveStage=0;wi=0;weapons[0].mag=12;weapons[0].reserve=48;weapons[1].mag=30;weapons[1].reserve=90;zeds.length=0;bullets.length=0;particles.length=0;for(let i=0;i<10;i++){let x=rand(380,1330),y=rand(480,815);if(Math.abs(y-650)<80)y+=Math.sign(y-650||1)*90;spawnZed(x,y)}loot.forEach(a=>a.used=false);recorded=false;gameOver=false;ui.end.classList.add('hidden');startGame()}
document.getElementById('start-btn').onclick=startGame;document.getElementById('resume-btn').onclick=()=>{paused=false;ui.pause.classList.add('hidden');last=performance.now();requestAnimationFrame(loop)};document.getElementById('restart-btn').onclick=restart;document.getElementById('pause-btn').onclick=()=>{if(!started||gameOver)return;paused=true;ui.pause.classList.remove('hidden')};document.getElementById('journal-close').onclick=()=>ui.journal.classList.add('hidden');

input.newString:
document.getElementById('journal-close').onclick=()=>ui.journal.classList.add('hidden');
let aim={x:850,y:650},mouseDown=false,touchFire=false,stick={x:0,y:0},sprinting=false;
addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.repeat)return;if(e.key.toLowerCase()==='q')swapWeapon();if(e.key.toLowerCase()==='r')reload();if(e.key==='Escape'||e.key.toLowerCase()==='p'){if(started&&!gameOver){paused=!paused;ui.pause.classList.toggle('hidden',!paused);if(!paused){last=performance.now();requestAnimationFrame(loop)}}}});
addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
function pointerPos(e){let rect=canvas.getBoundingClientRect();return{x:e.clientX-rect.left+camera.x,y:e.clientY-rect.top+camera.y}}
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='mouse')aim=pointerPos(e)});canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){aim=pointerPos(e);mouseDown=true;canvas.setPointerCapture(e.pointerId)}});addEventListener('pointerup',e=>{if(e.pointerType==='mouse')mouseDown=false});
function swapWeapon(){wi=1-wi;setWeapon();toast(weapons[wi].name)}
function reload(){let w=weapons[wi];if(w.reload>0||w.mag===w.capacity||w.reserve===0)return;w.reload=1.15;toast('RELOADING…')}
document.getElementById('reload-touch').onclick=reload;document.getElementById('swap-touch').onclick=swapWeapon;
const zone=document.getElementById('stick-zone'),knob=document.getElementById('stick-knob');let stickId=null;
function moveStick(e){let r=zone.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,len=Math.hypot(dx,dy),max=32;if(len>max){dx=dx/len*max;dy=dy/len*max}stick.x=dx/max;stick.y=dy/max;knob.style.transform=`translate(${dx}px,${dy}px)`}
zone.addEventListener('pointerdown',e=>{e.preventDefault();stickId=e.pointerId;zone.setPointerCapture(stickId);moveStick(e)});zone.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e)});zone.addEventListener('pointerup',e=>{if(e.pointerId===stickId){stick={x:0,y:0};knob.style.transform='translate(0,0)';stickId=null}});zone.addEventListener('pointercancel',()=>{stick={x:0,y:0};knob.style.transform='translate(0,0)';stickId=null});
const fireBtn=document.getElementById('fire-touch');fireBtn.addEventListener('pointerdown',e=>{e.preventDefault();touchFire=true;fireBtn.setPointerCapture(e.pointerId)});fireBtn.addEventListener('pointerup',()=>touchFire=false);fireBtn.addEventListener('pointercancel',()=>touchFire=false);document.getElementById('sprint-touch').addEventListener('pointerdown',()=>sprinting=true);document.getElementById('sprint-touch').addEventListener('pointerup',()=>sprinting=false);document.getElementById('sprint-touch').addEventListener('pointercancel',()=>sprinting=false);
